const items = $input.all();

return items.map(item => {
  let text = item.json.text || "";

  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  const data = JSON.parse(text);

  let publicRate;

  if (data.platform === "Apple Music") {
    publicRate = 0.01;
  } else if (data.platform === "Spotify") {
    publicRate = 0.0035;
  } else if (data.platform === "YouTube Music") {
    publicRate = 0.0025;
  } else {
    publicRate = Number(data.royalty_rate) || 0;
  }

  return {
    json: {
      ...data,
      public_rate: publicRate
    }
  };
});

const items = $input.all();

return items.map(item => {
  const html = item.json.data || "";

  const match = html.match(/Our average per play rate is \$0\.01/i);

  return {
    json: {
      public_rate: match ? 0.01 : null,
      rate_source: "Apple Music for Artists",
      rate_note: match
        ? "Apple Music published an average per-play rate of $0.01 for Apple Music individual paid plans in 2020."
        : "Public rate could not be extracted from the source page."
    }
  };
});

const rateItems = $input.all();
const originalItems = $('Normalize Royalty Data').all();

return rateItems.map((item, index) => {
  const rateData = item.json;
  const originalData = originalItems[index].json;

  const streams = Number(originalData.streams);
  const publicRate = Number(rateData.public_rate);
  const actualPaid = Number(originalData.actual_paid);

  const expectedRoyalty = streams * publicRate;
  const leakage = expectedRoyalty - actualPaid;

  let severity;
  let auditStatus;
  let disputeRequired;

  if (leakage > 0) {
    auditStatus = "UNDERPAID";
    disputeRequired = true;

    if (leakage >= 100) {
      severity = "HIGH";
    } else if (leakage >= 25) {
      severity = "MEDIUM";
    } else {
      severity = "LOW";
    }
  } else if (leakage === 0) {
    auditStatus = "CORRECT";
    disputeRequired = false;
    severity = "NONE";
  } else {
    auditStatus = "OVERPAID";
    disputeRequired = false;
    severity = "NONE";
  }

  return {
    json: {
      ...originalData,
      public_rate: publicRate,
      rate_source: rateData.rate_source,
      rate_note: rateData.rate_note,
      expected_royalty: expectedRoyalty,
      leakage: leakage,
      severity: severity,
      audit_status: auditStatus,
      dispute_required: disputeRequired
    }
  };
});

